import {escapeHTML as esc} from './core.js';
const L=(en,pt,es,ru)=>({en,pt,es,ru});
export const BOOKS=[
 {id:'comfort',title:'O livro do conforto',author:'Matt Haig',language:'Português (Brasil)',moods:['sad','overwhelmed','unsure'],url:'https://loja.intrinseca.com.br/o-livro-do-conforto/',note:L('Short reflections to read a little at a time when a longer book feels demanding. Publisher rating: 16+.','Reflexões curtas para ler aos poucos quando um livro longo parece exigir muito. Classificação da editora: 16+.','Reflexiones breves para leer poco a poco cuando un libro largo resulta exigente. Edad indicada por la editorial: 16+.','Короткие размышления для неспешного чтения, когда длинная книга требует слишком много сил. Возраст издателя: 16+.')},
 {id:'happiness-trap',title:'The Happiness Trap, Second Edition',author:'Russ Harris',language:'English',moods:['anxious','overwhelmed'],url:'https://www.shambhala.com/the-happiness-trap-second-edition.html',note:L('An introduction to ACT ideas: notice difficult thoughts and choose actions connected to your values.','Uma introdução às ideias da ACT: perceber pensamentos difíceis e escolher ações ligadas aos seus valores.','Una introducción a ideas de ACT: observar pensamientos difíciles y elegir acciones vinculadas a tus valores.','Введение в идеи ACT: замечать трудные мысли и выбирать действия, связанные с вашими ценностями.')},
 {id:'meaning',title:'Em busca de sentido',author:'Viktor E. Frankl',language:'Português (Brasil)',moods:['hopeless','hopeful'],url:'https://www.livrariavozes.com.br/embuscadesentido8532606261/p?idsku=264',note:L('An optional deeper reflection on meaning during adversity. Includes accounts of the Holocaust and concentration camps.','Uma reflexão mais profunda e opcional sobre o sentido diante da adversidade. Inclui relatos do Holocausto e de campos de concentração.','Una reflexión más profunda y opcional sobre el sentido ante la adversidad. Incluye relatos del Holocausto y campos de concentración.','Необязательное глубокое размышление о смысле в трудностях. Содержит описания Холокоста и концлагерей.')},
 {id:'grief',title:'A anatomia de um luto',author:'C. S. Lewis',language:'Português (Brasil)',moods:['grief'],url:'https://thomasnelson.com.br/products/a-anatomia-de-um-luto-cs-lewis',note:L('One person’s account of bereavement and difficult questions about Christian faith.','Um relato pessoal de luto e perguntas difíceis sobre a fé cristã.','Un relato personal de duelo y preguntas difíciles sobre la fe cristiana.','Личный рассказ об утрате и трудных вопросах христианской веры.')},
 {id:'delights',title:'The Book of Delights',author:'Ross Gay',language:'English',moods:['grateful','peaceful','hopeful'],url:'https://www.hachettebookgroup.com/titles/ross-gay/the-book-of-delights/9781643753287/',note:L('Brief essays about ordinary moments: a starting point for noticing something meaningful today.','Ensaios breves sobre momentos cotidianos: um ponto de partida para perceber algo significativo hoje.','Ensayos breves sobre momentos cotidianos: un punto de partida para notar algo significativo hoy.','Короткие эссе об обычных мгновениях: повод заметить что-то значимое сегодня.')},
 {id:'return',title:'The Return of the Prodigal Son',author:'Henri J. M. Nouwen',language:'English',moods:['lonely','unsure','hopeless'],url:'https://www.henrinouwen.org/books/the-return-of-the-prodigal-son',note:L('A Christian reflection on belonging, reconciliation and receiving love through art and the biblical parable.','Uma reflexão cristã sobre pertencimento, reconciliação e acolher o amor, pela arte e pela parábola bíblica.','Una reflexión cristiana sobre pertenencia, reconciliación y recibir amor a través del arte y la parábola bíblica.','Христианское размышление о принадлежности, примирении и принятии любви через искусство и библейскую притчу.')}
];
export function booksForMood(mood,language){return BOOKS.filter(b=>b.moods.includes(mood||'unsure')).sort((a,b)=>Number(b.language.startsWith(language==='pt'?'Português':'English'))-Number(a.language.startsWith(language==='pt'?'Português':'English'))).slice(0,2);}
export function bookRecommendations(mood,language,t,ico){const books=booksForMood(mood,language);if(!books.length)return '';return `<section class="book-recommendations"><div class="eyebrow">${ico('book')}${esc(t('read'))}</div><h2>${esc(t('pBooks'))}</h2><p>${esc(t('pBookIntro'))}</p>${books.map(b=>`<article class="book-pick"><div class="book-spine" aria-hidden="true">${ico('book')}</div><div><h3>${esc(b.title)}</h3><span class="book-author">${esc(b.author)} · ${esc(b.language)}</span><p>${esc(b.note[language]||b.note.en)}</p><a class="text-button" href="${esc(b.url)}" target="_blank" rel="noopener noreferrer">${esc(t('pBookSource'))}${ico('external')}</a></div></article>`).join('')}<small>${esc(t('pBookNote'))}</small></section>`;}
